\label{Theorem1.1}
Let $N\geqslant3$, $s\in(0,1)$ and $p\in (2^{*}_{s},2^{*})$.
Then we have the following results.

\begin{enumerate}
\item [(1)]
For all $u\in E$, we have
\begin{equation*}
\begin{aligned}
\int_{\mathbb{R}^{N}}
|u|^{p}
\mathrm{d}x
\leqslant
C_{N,p,s}
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{\frac{2N-p(N-2)}{2(1-s)}}
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{\frac{p(N-2s)-2N}{2(1-s)}},
\end{aligned}
\end{equation*}
where $C_{N,p,s}>0$ (independent of $u$) is the best constant.

\item [(2)]
There exists a radial non-negative optimizer $u\in E$ for inequality \eqref{GN}.

\item [(3)]
Set $Q=\lambda_{1}u(\lambda_{2}x)$, where
\begin{equation*}
\begin{aligned}
\begin{cases}
\lambda_{1}=
\left[
\frac{p(N-2s)-2N}{2N-p(N-2)}
\right]^{\frac{1}{(1-s)(p-2)}}
\left[
\frac{2p(1-s)}{p(N-2s)-2N}
\frac{1}{\|u\|_{L^{p}(\mathbb{R}^{N})}^{p}}
\right]^{\frac{1}{p-2}},\\
\lambda_{2}=
\left[
\frac{p(N-2s)-2N}{2N-p(N-2)}
\right]^{\frac{1}{2-2s}}.
\end{cases}
\end{aligned}
\end{equation*}
Then $Q$ is a radial non-negative weak solution of equation \eqref{P}, and it is also an optimizer for inequality \eqref{GN}. Moreover, we have
\begin{equation}\label{1.5}
\begin{aligned}
\|Q\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
=&
\frac{p(N-2s)-2N}{2N-p(N-2)}
\|Q\|_{D^{s,2}(\mathbb{R}^{N})}^{2}\\
=&
\frac{p(N-2s)-2N}{2p(1-s)}
\|Q\|_{L^{p}(\mathbb{R}^{N})}^{p},
\end{aligned}
\end{equation}

\begin{equation}\label{1.6}
\begin{aligned}
\frac{N-2}{2}
\|Q\|^{2}_{D^{1,2}(\mathbb{R}^{N})}
+
\frac{N-2s}{2}
\|Q\|^{2}_{D^{s,2}(\mathbb{R}^{N})}
=\frac{N}{p}\|Q\|_{L^{p}(\mathbb{R}^{N})}^{p},
\end{aligned}
\end{equation}
and
\begin{equation}\label{1.7}
\begin{aligned}
C_{N,p,s}^{-1}=
\left(
\frac{2N-p(N-2)}{2p(1-s)}
\right)
^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\frac{p(N-2s)-2N}{2p(1-s)}
\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}
\|Q\|_{L^{p}(\mathbb{R}^{N})}^{\frac{p(p-2)}{2}}.
\end{aligned}
\end{equation}
\end{enumerate}

\label{Theorem1.2}
Let $N\geqslant3$, $s\in(0,1)$ and $p\in (2^{*}_{s},2^{*})$. Then equation \eqref{P} has a radial ground state solution $\Phi\in E$, which satisfies
\begin{equation*}
\begin{aligned}
I(\Phi)=\inf_{u\in \mathcal{N}}I(u)=c,
\end{aligned}
\end{equation*}
where $I$ is the energy functional of equation \eqref{P} defined as follows
\begin{equation*}
\begin{aligned}
I(u)=
\frac{1}{2}
\left(
\int_{\mathbb{R}^{N}}
|\nabla u|^{2}
\mathrm{d}x
+
\int_{\mathbb{R}^{N}}\int_{\mathbb{R}^{N}}\frac{|u(x)-u(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x\mathrm{d}y\right)
-
\frac{1}{p}
\int_{\mathbb{R}^{N}}
|u|^{p}
\mathrm{d}x,
\end{aligned}
\end{equation*}
and $\mathcal{N}:=\{u\in E\backslash\{0\}|\langle I'(u),u\rangle=0\}$ is the Nehari manifold.

\label{Theorem1.3}
Let $N\geqslant3$, $s\in(0,1)$ and $p\in (2^{*}_{s},2^{*})$.
Then equation \eqref{P} has a solution $\Psi\in E$, which satisfies
\begin{equation*}
\begin{aligned}
P(\Psi)=\frac{N-2}{2}
\|\Psi\|^{2}_{D^{1,2}(\mathbb{R}^{N})}
+
\frac{N-2s}{2}
\|\Psi\|^{2}_{D^{s,2}(\mathbb{R}^{N})}
-\frac{N}{p}\|\Phi\|_{L^{p}(\mathbb{R}^{N})}^{p}=0,
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
I(\Psi)=\inf_{u\in \mathcal{M}}I(u)=c
\end{aligned}
\end{equation*}
where $\mathcal{M}:=\{u\in E\backslash\{0\}|P(u)=0\}$ is the Nehari-Poho\v{z}aev manifold.

\label{Theorem1.4}
Let $N\geqslant3$, $s\in(0,1)$ and $p\in (2^{*}_{s},2^{*})$. Then we have the following results.

\begin{enumerate}
\item [(1)]
The best constant of \eqref{1.1} is
\begin{equation*}
\begin{aligned}
C_{N,p,s}^{-1}
=\left(
\frac{2N-p(N-2)}{2p(1-s)}
\right)
^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\frac{p(N-2s)-2N}{2p(1-s)}
\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}
\left[
\frac{2p}{p-2}
c
\right]^{\frac{p-2}{2}}
\end{aligned}
\end{equation*}
where $c=\inf\limits_{u\in \mathcal{N}}I(u)$.

\item [(2)]
The optimizer $Q$ is not only a weak solution of equation \eqref{P}, but it is also a ground state solution and satisfies
\begin{equation*}
\begin{aligned}
I(Q)=c~~\mathrm{and}~~P(Q)=0.
\end{aligned}
\end{equation*}
\end{enumerate}

\label{Lemma2.1}
$E\hookrightarrow D^{1,2}(\mathbb{R}^{N})$ and
$E\hookrightarrow D^{s,2}(\mathbb{R}^{N})$.

It is easy to see that
\begin{equation*}
\begin{aligned}
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
\leqslant \|u\|_{E}^{2},
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
\leqslant \|u\|_{E}^{2}.
\end{aligned}
\end{equation*}
Therefore $E\hookrightarrow D^{1,2}(\mathbb{R}^{N})$ and
$E\hookrightarrow D^{s,2}(\mathbb{R}^{N})$.

Using H\"{o}lder's inequality, we have
\begin{equation}\label{2.1}
\begin{aligned}
\int_{\mathbb{R}^{N}}
|u|^{t}
\mathrm{d}x
\leqslant&
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2s}}
\mathrm{d}x
\right)
^{\frac{(N-2s)[2N-t(N-2)]}{4N(1-s)}}
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2}}
\mathrm{d}x
\right)
^{\frac{(N-2)[t(N-2s)-2N]}{4N(1-s)}}.
\end{aligned}
\end{equation}
From Lemma \ref{Lemma2.1}, we know that:
\begin{equation*}
\begin{aligned}
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2s}}
\mathrm{d}x
\right)^{\frac{2}{2_{s}^{*}}}
\leqslant
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
\leqslant \|u\|_{E}^{2},
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2}}
\mathrm{d}x
\right)^{\frac{2}{2^{*}}}
\leqslant
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
\leqslant \|u\|_{E}^{2}.
\end{aligned}
\end{equation*}
Then we get
\begin{equation*}
\begin{aligned}
\int_{\mathbb{R}^{N}}
|u|^{t}
\mathrm{d}x
\leqslant&
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2s}}
\mathrm{d}x
\right)
^{\frac{(tN-2N-2t)(N-2s)}{4N(s-1)}}
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2}}
\mathrm{d}x
\right)
^{\frac{(tN-2N-2ts)(N-2)}{4N(1-s)}}\\
\leqslant&\|u\|_{E}^{t}<\infty.
\end{aligned}
\end{equation*}
The proof is complete.

\label{Lemma2.3}
\cite[Theorem 1.1]{Cotsiolis-Tavoularis2004JMAA}
Let
$s\in(0,1]$
and $N>2s$.
Then there exists a constant
$S_{s}>0$
such that for
any
$u\in D^{s,2}(\mathbb{R}^{N})$,
\begin{equation*}
\begin{aligned}
\|u\|_{L^{2_{s}^{*}}(\mathbb{R}^{N})}^{2}
\leqslant
S_{s}^{-1}
\|u\|^{2}_{D^{s,2}}(\mathbb{R}^{N}).
\end{aligned}
\end{equation*}

\label{Lemma2.4}
Let $N\geqslant 3$, $s\in(0,1)$ and $q\in(2^{*}_{s},2^{*})$. Then the following inequality holds
\begin{equation*}
\begin{aligned}
\int_{\mathbb{R}^{N}}|u|^{q}\mathrm{d}x\leqslant2C(N+1)^{2}
\left(\sup_{z\in \mathbb{R}^{N}}
\int_{B(z,1)}
|u|^{q}
\mathrm{d}x\right)^{\frac{q-2}{q}}
\|u\|_{E}^{2},
\end{aligned}
\end{equation*}
for all $u\in E$.

Let $u\in E$ and $q\in(2_{s}^{*},2^{*})$.
From H\"{o}lder's inequality and Lemma \ref{Lemma2.3}, we have
\begin{equation}\label{2.2}
\begin{aligned}
&\int_{B(z,1)}|u|^{q}\mathrm{d}x\\
\leqslant&
C
\left(
\int_{B(z,1)}\int_{B(z,1)}\frac{|u(x)-u(y)|^{2}}{|x-y|^{N+2s}}\mathrm{d}x\mathrm{d}y
+
\int_{B(z,1)}
|\nabla u|^{2}
\mathrm{d}x\right)^{\frac{q}{2}}.
\end{aligned}
\end{equation}
Applying \eqref{2.2}, we know that
\begin{equation*}
\begin{aligned}
&\int_{B(z,1)}|u|^{q}\mathrm{d}x\\
=&
\left(\int_{B(z,1)}|u|^{q}\mathrm{d}x\right)^{\frac{2}{q}}
\left(\int_{B(z,1)}|u|^{q}\mathrm{d}x\right)
^{\frac{q-2}{q}}\\
\leqslant&
C
\left(
\int_{B(z,1)}\int_{B(z,1)}\frac{|u(x)-u(y)|^{2}}{|x-y|^{N+2s}}\mathrm{d}x\mathrm{d}y
+
\int_{B(z,1)}
|\nabla u|^{2}
\mathrm{d}x\right)
\left(\int_{B(z,1)}|u|^{q}\mathrm{d}x\right)
^{\frac{q-2}{q}}.
\end{aligned}
\end{equation*}
Covering $\mathbb{R}^{N}$ by balls of radius $1$,
in such a way that each point of $\mathbb{R}^{N}$ is contained in at most $N+1$ balls.
We get
\begin{equation*}
\begin{aligned}
&\int_{\mathbb{R}^{N}}|u|^{q}\mathrm{d}x\\
\leqslant& C(N+1)
\left(\sup_{z\in \mathbb{R}^{N}}
\int_{B(z,1)}
|u|^{q}
\mathrm{d}x\right)^{\frac{q-2}{q}}
\left(
\int_{\mathbb{R}^{N}}\int_{\mathbb{R}^{N}}\frac{|u(x)-u(y)|^{2}}{|x-y|^{N+2s}}\mathrm{d}y\mathrm{d}x
+
\int_{\mathbb{R}^{N}}
|\nabla u|^{2}
\mathrm{d}x\right).
\end{aligned}
\end{equation*}

\label{Lemma2.5}
Let $N\geqslant3$, $0<s<1$, $q\in (2^{*}_{s},2^{*})$, and $\{u_{n}\}$ be a bounded sequence in $E$ satisfing  $\lim\limits_{n\to\infty}\int_{\mathbb{R}^{N}}|u_{n}|^{q}\mathrm{d}x>0$.
Then there exists $\{z_{n}\}\subset \mathbb{R}^{N}$ such that $\{\bar{u}_{n}:=u_{n}(x+z_{n})\}$ convergence strongly to $\bar{u}\not\equiv0$ in $L^{q}_{loc}(\mathbb{R}^{N})$.

Note that $\{u_{n}\}$ is a bounded sequence in $E$.
Up to a subsequence,
we may assume that
\begin{equation*}
\begin{aligned}
u_{n}\rightharpoonup u
~
\mathrm{in}
~
E,~
u_{n}\rightarrow u
~
\mathrm{a.e. ~in}
~\mathbb{R}^{N},
u_{n}\rightarrow u
~
\mathrm{in}
~
L^{q}_{loc}(\mathbb{R}^{N}).
\end{aligned}
\end{equation*}
Applying Lemma \ref{Lemma2.4} and $\lim\limits_{n\to\infty}\int_{\mathbb{R}^{N}}|u_{n}|^{q}\mathrm{d}x>0$,
there exists
$C>0$
such that
\begin{equation*}
\begin{aligned}
\sup_{z\in \mathbb{R}^{N}}
\int_{B(z,1)}
|u|^{q}
\mathrm{d}x\geqslant C>0.
\end{aligned}
\end{equation*}
Note that $\{u_{n}\}$ is bounded in $E$ and $E\hookrightarrow L^{q}(\mathbb{R}^{N})$,
we have
\begin{equation*}
\begin{aligned}
\sup_{z\in \mathbb{R}^{N}}
\int_{B(z,1)}
|u|^{q}
\mathrm{d}x\leqslant\int_{\mathbb{R}^{N}}
|u_{n}|^{q}
\mathrm{d}x \leqslant C.
\end{aligned}
\end{equation*}
Hence, there exists $C_{0}$ such that
\begin{equation*}
\begin{aligned}
C_{0}
\leqslant
\sup_{z\in \mathbb{R}^{N}}
\int_{B(z,1)}
|u|^{q}
\mathrm{d}x\leqslant C_{0}^{-1}.
\end{aligned}
\end{equation*}
From the above inequality,
there exists
$z_{n}\in \mathbb{R}^{N}$
such that
\begin{equation*}
\begin{aligned}
\int_{B(z_{n},1)}
|u_{n}|^{q}
\mathrm{d}x
\geqslant
\sup_{z\in \mathbb{R}^{N}}
\int_{B(z,1)}
|u_{n}|^{q}
\mathrm{d}x
-
\frac{C}{2n}
\geqslant
C_{1}>0.
\end{aligned}
\end{equation*}
Set $\bar{u}_{n}:=u_{n}(x+z_{n})$. Then $\|\bar{u}_{n}\|_{E}=\|u_{n}\|_{E}$ and
\begin{equation*}
\begin{aligned}
\int_{B(0,1)}
|\bar{u}_{n}|^{q}
\mathrm{d}x
\geqslant
C_{1}>0.
\end{aligned}
\end{equation*}
Up to a subsequence,
there exists
$\bar{u}$
such that
\begin{equation*}
\begin{aligned}
\bar{u}_{n}\rightharpoonup \bar{u}
\;
\mathrm{in}
~
E,
\;\;
\bar{u}_{n}\rightarrow \bar{u}
~
\mathrm{a.e. ~in}
~
\mathbb{R}^{N}.
\end{aligned}
\end{equation*}
Using the compact embedding
$E
\hookrightarrow
L^{q}_{loc}(\mathbb{R}^{N})$,
we deduce that
$\bar{u}\not\equiv0$.

\label{Lemma3.1}
Let $N\geqslant3$, $s\in(0,1)$ and $p\in (2^{*}_{s},2^{*})$.
For all $u\in E$, there exists $C_{N,p,s}>0$ (independent of $u$) such that
\begin{equation*}
\begin{aligned}
\int_{\mathbb{R}^{N}}
|u|^{p}
\mathrm{d}x
\leqslant
C_{N,p,s}
\left(
\int_{\mathbb{R}^{N}}
\int_{\mathbb{R}^{N}}
\frac{|u(x)-u(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x
\mathrm{d}y
\right)
^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\int_{\mathbb{R}^{N}}
|\nabla u|^{2}
\mathrm{d}x
\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}.
\end{aligned}
\end{equation*}

From Lemma \ref{Lemma2.3}, we have
\begin{equation}\label{3.1}
\begin{aligned}
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2s}}
\mathrm{d}x
\right)
^{\frac{N-2s}{N}}
\leqslant&
S_{s}^{-1}
\int_{\mathbb{R}^{N}}
\int_{\mathbb{R}^{N}}
\frac{|u(x)-u(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x
\mathrm{d}y,
\end{aligned}
\end{equation}
and
\begin{equation}\label{3.2}
\begin{aligned}
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2}}
\mathrm{d}x
\right)
^{\frac{N-2}{N}}
\leqslant&
S_{1}^{-1}
\int_{\mathbb{R}^{N}}
|\nabla u|^{2}
\mathrm{d}x.
\end{aligned}
\end{equation}
Plugging \eqref{3.1} and \eqref{3.2} into \eqref{2.1}, we deduce that
\begin{equation*}
\begin{aligned}
\int_{\mathbb{R}^{N}}
|u|^{p}
\mathrm{d}x
\leqslant&
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2s}}
\mathrm{d}x
\right)
^{\frac{N-2s}{N}\cdot\frac{2N-p(N-2)}{4(1-s)}}
\left(
\int_{\mathbb{R}^{N}}
|u|^{\frac{2N}{N-2}}
\mathrm{d}x
\right)
^{\frac{N-2}{N}\cdot
\frac{p(N-2s)-2N}{4(1-s)}}\\
\leqslant&
C
\left(
\int_{\mathbb{R}^{N}}
\int_{\mathbb{R}^{N}}
\frac{|u(x)-u(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x
\mathrm{d}y
\right)
^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\int_{\mathbb{R}^{N}}
|\nabla u|^{2}
\mathrm{d}x
\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}.
\end{aligned}
\end{equation*}

\label{Lemma3.2}
Let $N\geqslant3$, $s\in(0,1)$ and $p\in (2^{*}_{s},2^{*})$.
There exists a radial minimzing sequence $\{u_{n}\}\subset E$ of $C_{N,p,s}^{-1}$ such that
\begin{equation*}
\begin{aligned}
\|u_{n}\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
=
\|u_{n}\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
=1.
\end{aligned}
\end{equation*}

{\bf Step 1.}
From Lemma \ref{Lemma3.1}, we know that there exists a minimzing sequence $\{w_{n}\}\subset E$ such that
\begin{equation*}
\begin{aligned}
\lim\limits_{n\to\infty}
W(w_{n})=C_{N,p,s}^{-1}.
\end{aligned}
\end{equation*}
It is easy to see that $\{|w_{n}|\}\subset E$ and $\lim\limits_{n\to\infty}
W(|w_{n}|)=C_{N,p,s}^{-1}$.

Let $|w_{n}|^{*}$ be the symmetric decreasing rearrangement of $|w_{n}|$.
From [14] and [21], one has
\begin{equation*}
\begin{aligned}
\||w_{n}|^{*}\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
\leqslant
\||w_{n}|\|_{D^{1,2}(\mathbb{R}^{N})}^{2},
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
\||w_{n}|^{*}\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
\leqslant
\||w_{n}|\|_{D^{1,2}(\mathbb{R}^{N})}^{2},
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
\int_{\mathbb{R}^{N}}
||w_{n}|^{*}|^{p}
\mathrm{d}x
=
\int_{\mathbb{R}^{N}}
|w_{n}|^{p}
\mathrm{d}x.
\end{aligned}
\end{equation*}
Hence
$C_{N,p,s}^{-1}\leqslant\lim\limits_{n\to\infty}
W(|w_{n}|^{*})\leqslant\lim\limits_{n\to\infty}
W(|w_{n}|)=C_{N,p,s}^{-1}$.
Set
\begin{equation*}
\begin{aligned}
v_{n}=|w_{n}|^{*}.
\end{aligned}
\end{equation*}
Then $\lim\limits_{n\to\infty}
W(v_{n})=C_{N,p,s}^{-1}$.


{\bf Step 2.}
We rescale the sequence $\{v_{n}\}$ by
\begin{equation*}
\begin{aligned}
u_{n}=\lambda_{1,n}v_{n}(\lambda_{2,n}x),
\end{aligned}
\end{equation*}
where
\begin{equation*}
\begin{aligned}
\lambda_{1,n}
=
\frac
{\left[\int_{\mathbb{R}^{N}}
\int_{\mathbb{R}^{N}}
\frac{|v_{n}(x)-v_{n}(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x
\mathrm{d}y
\right]^{\frac{N-2}{1-s}}}
{\left[\int_{\mathbb{R}^{N}}
|\nabla v_{n}(x)|^{2}
\mathrm{d}x
\right]^{\frac{N-2s}{1-s}}},
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
\lambda_{2,n}
=
\left[
\frac
{\int_{\mathbb{R}^{N}}
\int_{\mathbb{R}^{N}}
\frac{|v_{n}(x)-v_{n}(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x
\mathrm{d}y}
{\int_{\mathbb{R}^{N}}
|\nabla v_{n}(x)|^{2}
\mathrm{d}x}
\right]^{\frac{1}{2-2s}}.
\end{aligned}
\end{equation*}
Then
\begin{equation*}
\begin{aligned}
1=&
\int_{\mathbb{R}^{N}}
\int_{\mathbb{R}^{N}}
\frac{|u_{n}(x)-u_{n}(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x
\mathrm{d}y\\
=&
\lambda_{1,n}^{2}
\lambda_{2,n}^{2s-N}
\int_{\mathbb{R}^{N}}
\int_{\mathbb{R}^{N}}
\frac{|v_{n}(x)-v_{n}(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x
\mathrm{d}y,
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
1=
\int_{\mathbb{R}^{N}}
|\nabla u_{n}|^{2}
\mathrm{d}x
=&
\lambda_{1,n}^{2}
\lambda_{2,n}^{2-N}
\int_{\mathbb{R}^{N}}
|\nabla v_{n}(x)|^{2}
\mathrm{d}x,
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
\int_{\mathbb{R}^{N}}
|u_{n}|^{p}
\mathrm{d}x
=&\lambda_{1,n}^{p}
\lambda_{2,n}^{-N}
\int_{\mathbb{R}^{N}}
|v_{n}(x)|^{p}
\mathrm{d}x.
\end{aligned}
\end{equation*}
{\bf Step 3.}
The Weinstein functional $W(\cdot)$ is invariant with respect to our scaling:
\begin{equation*}
\begin{aligned}
W(u_{n})
=&
\frac{\left(
\|u_{n}\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
\right)
^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\|u_{n}\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}}
{\int_{\mathbb{R}^{N}}
|u|^{p}
\mathrm{d}x}\\
=&
\frac{[\lambda_{1,n}^{2}
\lambda_{2,n}^{2s-N}]^{\frac{2N-p(N-2)}{4(1-s)}}[\lambda_{1,n}^{2}
\lambda_{2,n}^{2-N}]^{\frac{p(N-2s)-2N}{4(1-s)}}}{\lambda_{1,n}^{p}
\lambda_{2,n}^{-N}}
W(v_{n})\\
=&W(v_{n}).
\end{aligned}
\end{equation*}
This impiles that $\{u_{n}\}\subset E$ is a radial bounded minimizing sequence.

\label{Lemma3.3}
Let $N\geqslant3$, $s\in(0,1)$ and $p\in (2^{*}_{s},2^{*})$.
Let $\{u_{n}\}\subset E$ be a radial minimzing sequence  of $C_{N,p,s}^{-1}$ which is in Lemma \ref{Lemma3.2}.
Then $u_{n}\to u\not\equiv 0$ in $E$, and
\begin{equation*}
\begin{aligned}
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
=
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
=1
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
W(u)=C_{N,p,s}^{-1}.
\end{aligned}
\end{equation*}

{\bf Step 1.}
From Lemma \ref{Lemma3.2}, we have $\|u_{n}\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
=
\|u_{n}\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
=1$ and
\begin{equation*}
\begin{aligned}
0<C_{N,p,s}
=&\lim\limits_{n\to\infty}
\frac
{\int_{\mathbb{R}^{N}}
|u_{n}|^{p}
\mathrm{d}x}
{\left(
\int_{\mathbb{R}^{N}}
\int_{\mathbb{R}^{N}}
\frac{|u_{n}(x)-u_{n}(y)|^{2}}{|x-y|^{N+2s}}
\mathrm{d}x
\mathrm{d}y
\right)
^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\int_{\mathbb{R}^{N}}
|\nabla u_{n}|^{2}
\mathrm{d}x
\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}}\\
=&\lim\limits_{n\to\infty}
\int_{\mathbb{R}^{N}}
|u_{n}|^{p}
\mathrm{d}x.
\end{aligned}
\end{equation*}
Combining $\lim\limits_{n\to\infty}
\int_{\mathbb{R}^{N}}
|u_{n}|^{p}
\mathrm{d}x\geqslant C>0$ and Lemma \ref{Lemma2.4}, one has that there exists a sequence of $\{z_{n}\}\subset \mathbb{R}^{N}$ such that
\begin{equation}\label{3.3}
\begin{aligned}
\int_{B(z_{n},1)}
|u_{n}|^{p}
\mathrm{d}x
\geqslant C_{1}>0.
\end{aligned}
\end{equation}
where $C_{1}>0$ is a constant independent of $u_{n}$.


{\bf Step 2.}
We show that $\{z_{n}\}$ is a bounded sequence in $\mathbb{R}^{N}$.
Suppose on the contrary that
$|z_{n}|\rightarrow\infty$
as
$n\rightarrow\infty$.
We have
\begin{align*}
\sup_{|x|>0}
|u_{n}(x)|
\leqslant
\frac{C}{|x|^{\frac{N-2}{2}}}
\|u_{n}\|_{D^{1,2}(\mathbb{R}^{N})}
\leqslant
\frac{C}{|x|^{\frac{N-2}{2}}}.
\end{align*}
For any
$\left[\frac{C_{1}}{|B(0,1)|}\right]^{\frac{1}{p}}>\varepsilon>0$,
there exists an $M>0$ such that for any $n>M$ we can deduce that
\begin{align*}
|u_{n}(x)|
\leqslant
\frac{C}
{||x_{n}|-1|^{\frac{N-2}{2}}}
\leqslant
\varepsilon,
\ ~x\in B^{c}(0,||x_{n}|-1|).
\end{align*}
Note that
$B(z_{n},1)\subset B^{c}(0,||x_{n}|-1|)$.
Then
\begin{align*}
\int_{B(z_{n},1)}
|u_{n}|^{p}
\mathrm{d}x
\leqslant
\varepsilon^{p}
\int_{B(z_{n},1)}
\mathrm{d}x
=
\varepsilon^{p}
|B(z_{n},1)|
=
\varepsilon^{p}
|B(0,1)|
<C_{1}.
\end{align*}
This contradicts \eqref{3.3}.
Then we know that there exists $C>0$ such that $B(z_{n},1)\subset B(0,C)$ and
\begin{equation*}
\begin{aligned}
0<C_{1}\leqslant\int_{B(z_{n},1)}
|u_{n}|^{p}
\mathrm{d}x
\leqslant
\int_{B(0,C)}
|u_{n}|^{p}
\mathrm{d}x.
\end{aligned}
\end{equation*}
From $E\hookrightarrow\hookrightarrow L^{p}(B(0,C))$, we know that
\begin{equation*}
\begin{aligned}
u_{n}\rightharpoonup u\not\equiv 0.
\end{aligned}
\end{equation*}

{\bf Step 3.}
It follows from Brézis-Lieb Lemma, Lemma \ref{Lemma3.1} and Young's inequality that
\begin{equation*}
\begin{aligned}
0<&C_{N,p,s}\\
=&\lim\limits_{n\to\infty}
\int_{\mathbb{R}^{N}}
|u_{n}|^{p}
\mathrm{d}x\\
=&
\int_{\mathbb{R}^{N}}
|u|^{p}
\mathrm{d}x
+\lim\limits_{n\to\infty}
\int_{\mathbb{R}^{N}}
|u_{n}-u|^{p}
\mathrm{d}x\\
=&
C_{N,p,s}
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{\frac{2N-p(N-2)}{2(1-s)}}
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{\frac{p(N-2s)-2N}{2(1-s)}}\\
&+\lim\limits_{n\to\infty}
C_{N,p,s}
\|u_{n}-u\|_{D^{s,2}(\mathbb{R}^{N})}^{\frac{2N-p(N-2)}{2(1-s)}}
\|u_{n}-u\|_{D^{1,2}(\mathbb{R}^{N})}^{\frac{p(N-2s)-2N}{2(1-s)}}\\
\leqslant&
C_{N,p,s}
\left[
\frac{2N-p(N-2)}{2p(1-s)}
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{p}
+\frac{p(N-2s)-2N}{2p(1-s)}
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{p}
\right]\\
&+\lim\limits_{n\to\infty}
C_{N,p,s}
\left[
\frac{2N-p(N-2)}{2p(1-s)}
\|u_{n}-u\|_{D^{s,2}(\mathbb{R}^{N})}^{p}
+\frac{p(N-2s)-2N}{2p(1-s)}
\|u_{n}-u\|_{D^{1,2}(\mathbb{R}^{N})}^{p}
\right]\\
\leqslant&
C_{N,p,s}
\frac{2N-p(N-2)}{2p(1-s)}
\left[
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
+
\|u_{n}-u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
\right]^{\frac{p}{2}}\\
&+C_{N,p,s}
\frac{p(N-2s)-2N}{2p(1-s)}
\lim\limits_{n\to\infty}
\left[
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
+
\|u_{n}-u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
\right]^{\frac{p}{2}}\\
=&C_{N,p,s}
\frac{2N-p(N-2)}{2p(1-s)}
+C_{N,p,s}
\frac{p(N-2s)-2N}{2p(1-s)}\\
=&C_{N,p,s}.
\end{aligned}
\end{equation*}
Therefore all the above inequalities must be equalities. Hence,
\begin{equation*}
\begin{aligned}
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}=0~
\mathrm{or}~~\|u_{n}-u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}=0.
\end{aligned}
\end{equation*}
Note that $u\not\equiv0$. We know that $\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}\not=0$ and $\|u_{n}-u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}=0$ and
\begin{equation*}
\begin{aligned}
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
=
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
=1
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
W(u)=C_{N,p,s}^{-1}
\end{aligned}
\end{equation*}
Thus $u$ is a minimizer of $C_{N,p,s}^{-1}$.

\label{Lemma3.4}
Let $N\geqslant3$, $s\in(0,1)$ and $p\in (2^{*}_{s},2^{*})$.
Let $u$ be a minimizer of $C_{N,p,s}^{-1}$.
Then $Q=\lambda_{1}u(\lambda_{2}x)$ is a minimizer of $C_{N,p,s}^{-1}$, and also is a weak solution of
\begin{equation*}
\begin{aligned}
-\Delta Q
+(-\Delta)^{s}Q =
|Q|^{p-2}Q, \ \ x\in\mathbb{R}^{N},
\end{aligned}
\end{equation*}
where
\begin{equation*}
\begin{aligned}
\begin{cases}
\lambda_{1}=
\left[
\frac{p(N-2s)-2N}{2N-p(N-2)}
\right]^{\frac{1}{(1-s)(p-2)}}
\left[
\frac{2p(1-s)}{p(N-2s)-2N}
\frac{1}{\|u\|_{L^{p}(\mathbb{R}^{N})}^{p}}
\right]^{\frac{1}{p-2}},\\
\lambda_{2}=
\left[
\frac{p(N-2s)-2N}{2N-p(N-2)}
\right]^{\frac{1}{2-2s}}.
\end{cases}
\end{aligned}
\end{equation*}

From Lemma \ref{Lemma3.3}, one has that
$u$ is minimizer of $W(u)=C_{N,p,s}^{-1}$.
Then
\begin{equation*}
\begin{aligned}
\left.\frac{\mathrm{d}}
{\mathrm{d}\varepsilon}\right|_{\varepsilon=0}W(u+\varepsilon \varphi)=0,
\end{aligned}
\end{equation*}
for all $\varphi\in E$.
Thus, $u$ is a weak solution of the Euler-Lagrange equation
\begin{equation*}
\begin{aligned}
&-\Delta u
+\frac{2N-p(N-2)}{p(N-2s)-2N}
\frac{
\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
}
{\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}}
(-\Delta)^{s}u\\
=&
\frac{2p(1-s)}{p(N-2s)-2N}
\frac{\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}}
{\|u\|_{L^{p}(\mathbb{R}^{N})}^{p}}
|u|^{p-2}u, \ \ x\in\mathbb{R}^{N},
\end{aligned}
\end{equation*}
Set $Q=\lambda_{1}u(\lambda_{2}x)$, where
\begin{equation*}
\begin{aligned}
\begin{cases}
\lambda_{2}=
\left[
\frac{p(N-2s)-2N}{2N-p(N-2)}
\frac{
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
}
{\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}}\right]^{\frac{1}{2-2s}}\\
\lambda_{1}=\left[
\frac{p(N-2s)-2N}{2N-p(N-2)}
\frac{
\|u\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
}
{\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}}\right]^{\frac{1}{(1-s)(p-2)}}
\left[
\frac{2p(1-s)}{p(N-2s)-2N}
\frac{\|u\|_{D^{1,2}(\mathbb{R}^{N})}^{2}}
{\|u\|_{L^{p}(\mathbb{R}^{N})}^{p}}
\right]^{\frac{1}{p-2}}
\end{cases}
\end{aligned}
\end{equation*}
Then $Q$ is a weak solution of
\begin{equation*}
\begin{aligned}
-\Delta Q
+(-\Delta)^{s}Q =
|Q|^{p-2}Q, \ \ x\in\mathbb{R}^{N},
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
W(Q)=W(u).
\end{aligned}
\end{equation*}

\label{Lemma3.5}
We have
\begin{equation*}
\begin{aligned}
\|Q\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
=
\frac{p(N-2s)-2N}{2N-p(N-2)}
\|Q\|_{D^{s,2}(\mathbb{R}^{N})}^{2}
=
\frac{p(N-2s)-2N}{2p(1-s)}
\|Q\|_{L^{p}(\mathbb{R}^{N})}^{p},
\end{aligned}
\end{equation*}

\begin{equation*}
\begin{aligned}
\frac{N-2}{2}
\|Q\|^{2}_{D^{1,2}(\mathbb{R}^{N})}
+
