\|Q\|^{2}_{D^{s,2}(\mathbb{R}^{N})}
=\frac{N}{p}\int_{\mathbb{R}^{N}}|Q|^{p}\mathrm{d}x,
\end{aligned}
\end{equation*}
and
\begin{equation*}
\begin{aligned}
C_{N,p,s}^{-1}=
\left(
\frac{2N-p(N-2)}{2p(1-s)}
\right)
