^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\|Q\|_{D^{1,2}(\mathbb{R}^{N})}^{2}
\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}}
{\int_{\mathbb{R}^{N}}
|Q|^{p}
\mathrm{d}x}\\
=&
\frac
{\left(
\frac{2N-p(N-2)}{2p(1-s)}
\|Q\|_{L^{p}(\mathbb{R}^{N})}^{p}
\right)
^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\frac{p(N-2s)-2N}{2p(1-s)}
