\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}}
{\int_{\mathbb{R}^{N}}
|Q|^{p}
\mathrm{d}x}\\
=&
\left(
\frac{2N-p(N-2)}{2p(1-s)}
\right)
^{\frac{2N-p(N-2)}{4(1-s)}}
\left(
\frac{p(N-2s)-2N}{2p(1-s)}
\right)
^{\frac{p(N-2s)-2N}{4(1-s)}}
\left(
\int_{\mathbb{R}^{N}}
|Q|^{p}
