\begin{equation*}
\begin{aligned}
C_{1}(N-2)
(\bar{t}^{2s-2}-\bar{\bar{t}}^{2s-2})
=
C_{3}N
(\bar{t}^{2s}-\bar{\bar{t}}^{2s}).
